function toMmol(mgdl){ return mgdl/18; }
function categorizeFasting(mgdl){
  if(!(mgdl >= 0)) return null;
  if(mgdl >= 126) return {category:'糖尿病', en:'Diabetes', level:2};
  if(mgdl >= 100) return {category:'糖尿病前期', en:'Prediabetes', level:1};
  return {category:'正常', en:'Normal', level:0};
}
var EXPORTS = { toMmol:toMmol, categorizeFasting:categorizeFasting };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.BloodSugarForgePure = EXPORTS; }
